//
// Plugin: SelectNav.js ~ url: https://github.com/lukaszfiszer/selectnav.js
window.selectnav=function(){"use strict";var e=function(e,t){function c(e){var t;if(!e)e=window.event;if(e.target)t=e.target;else if(e.srcElement)t=e.srcElement;if(t.nodeType===3)t=t.parentNode;if(t.value)window.location.href=t.value}function h(e){var t=e.nodeName.toLowerCase();return t==="ul"||t==="ol"}function p(e){for(var t=1;document.getElementById("selectnav"+t);t++);return e?"selectnav"+t:"selectnav"+(t-1)}function d(e){a++;var t=e.children.length,n="",l="",c=a-1;if(!t){return}if(c){while(c--){l+=o}l+=" "}for(var v=0;v<t;v++){var m=e.children[v].children[0];if(typeof m!=="undefined"){var g=m.innerText||m.textContent;var y="";if(r){y=m.className.search(r)!==-1||m.parentNode.className.search(r)!==-1?f:""}if(i&&!y){y=m.href===document.URL?f:""}n+='<option value="'+m.href+'" '+y+">"+l+g+"</option>";if(s){var b=e.children[v].children[1];if(b&&h(b)){n+=d(b)}}}}if(a===1&&u){n='<option value="">'+u+"</option>"+n}if(a===1){n='<select class="selectnav" id="'+p(true)+'">'+n+"</select>"}a--;return n}e=document.getElementById(e);if(!e){return}if(!h(e)){return}if(!("insertAdjacentHTML"in window.document.documentElement)){return}document.documentElement.className+=" js";var n=t||{},r=n.activeclass||"active",i=typeof n.autoselect==="boolean"?n.autoselect:true,s=typeof n.nested==="boolean"?n.nested:true,o=n.indent||"-",u=n.label||"Menu",a=0,f=" selected ";e.insertAdjacentHTML("afterend",d(e));var l=document.getElementById(p());if(l.addEventListener){l.addEventListener("change",c)}if(l.attachEvent){l.attachEvent("onchange",c)}return l};return function(t,n){e(t,n)}}();

// Format <time> elements as DD.MM.YYYY (also reused after infinite scroll)
function simplifyFormatTimes() {
  document.querySelectorAll("time[datetime]").forEach(function (el) {
    var t = (el.getAttribute("datetime") || "").split("T")[0].split("-");
    if (t.length === 3) { el.insertAdjacentText("afterend", t[2] + "." + t[1] + "." + t[0]); el.remove(); }
  });
}

// Main navigation: rebuild the flat LinkList into a nested menu.
// Nesting depth is encoded with leading underscores in the link names
function initMainMenu() {
  var menu = document.getElementById("pixel-menu");
  if (!menu) return;
  var linkList = menu.querySelector(".LinkList");
  if (!linkList) return;
  var html = "";
  var level = -1;
  linkList.querySelectorAll("ul li").forEach(function (li) {
    var link = li.querySelector("a");
    if (!link) return;
    var text = li.textContent;
    var depth = (text.match(/_/g) || []).length;
    if (depth > level) html += "<ul>";
    if (depth < level) {
      for (var k = 0; k < level - depth; k++) html += "</ul></li>";
    }
    html += "<li><a href='" + link.getAttribute("href") + "'>" + text.replace(/_/g, "") + "</a>";
    level = depth;
  });
  for (var k = 0; k <= level; k++) {
    html += "</ul>";
    if (k !== 0) html += "</li>";
  }
  linkList.innerHTML = html;
  var topMenu = linkList.querySelector("ul");
  if (topMenu) topMenu.id = "nav1";
  selectnav("nav1");
  document.querySelectorAll("select.selectnav").forEach(function (sel) {
    sel.setAttribute("aria-label", "Site navigation");
  });
  menu.querySelectorAll("ul > li > ul").forEach(function (sub) {
    sub.parentElement.classList.add("parent");
  });
  menu.querySelectorAll(".widget").forEach(function (w) { w.setAttribute("style", "display:block!important;"); });
}

// Mobile drawer toggle
function initDrawer() {
  var buttons = document.querySelectorAll(".drawer");
  if (!buttons.length) return;
  var backdrop = document.createElement("div");
  backdrop.className = "drawer-backdrop";
  document.body.appendChild(backdrop);
  function isOpen() {
    return !!document.querySelector(".sidebar.open");
  }
  function setOpen(open) {
    document.querySelectorAll(".sidebar").forEach(function (sb) { sb.classList.toggle("open", open); });
    backdrop.classList.toggle("show", open);
    document.body.style.overflow = open ? "hidden" : "";
    buttons.forEach(function (btn) {
      var icon = btn.querySelector("i");
      if (icon) {
        icon.classList.toggle("fa-bars", !open);
        icon.classList.toggle("fa-xmark", open);
      }
      btn.setAttribute("aria-expanded", open ? "true" : "false");
    });
  }
  buttons.forEach(function (btn) {
    btn.setAttribute("aria-expanded", "false");
    btn.addEventListener("click", function (e) {
      e.preventDefault();
      setOpen(!isOpen());
    });
  });
  backdrop.addEventListener("click", function () { setOpen(false); });
  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape" && isOpen()) setOpen(false);
  });
}

// FeaturedPost widget: use the post image as the card background
function initFeaturedPostWidget() {
  document.querySelectorAll(".FeaturedPost .post-summary").forEach(function (card) {
    var image = card.querySelector(".image");
    if (image && image.getAttribute("src")) {
      card.setAttribute("style", "background-image:url(" + image.getAttribute("src") + ");");
    }
    card.insertAdjacentHTML("beforeend", "<div class='overlay'></div>");
  });
}

// Popular posts: trim snippets, ensure thumbnails
function initPopularPosts() {
  function snip(text, words) {
    return text.replace(/<.*?>/gi, "").split(/\s+/).slice(0, words - 1).join(" ");
  }
  document.querySelectorAll(".sbar .PopularPosts .item-snippet").forEach(function (el) {
    el.textContent = snip(el.textContent, 10);
  });
  document.querySelectorAll(".popular-posts li").forEach(function (li) {
    var thumb = li.querySelector(".item-thumbnail");
    if (!thumb) {
      var titleLink = li.querySelector(".item-title a");
      var url = titleLink ? titleLink.getAttribute("href") : "#";
      var content = li.querySelector(".item-content");
      if (content) content.insertAdjacentHTML("afterbegin", '<div class="item-thumbnail"><a href="' + url + '" target="_blank"><img alt="" loading="lazy" src="https://4.bp.blogspot.com/-wPwjv7-YYGY/Wc98wlDT8qI/AAAAAAAAAEE/mH8YkPl8qJAH9FMuFKcShQvXXYMmVyrIgCLcBGAs/w90-h72-p-k-no-nu/notfound.png"></a></div>');
    } else {
      var img = thumb.querySelector("img");
      if (img) {
        var src = img.getAttribute("src") || "";
        if (src.indexOf("w72-h72-p-k-no-nu") !== -1) img.setAttribute("src", src.replace("w72-h72-p-k-no-nu", "w90-h72-p-k-no-nu"));
      }
    }
  });
}

// Move author bio and social links into the article
function initPostInjections() {
  [["span[name=\"author-social\"]", ".post-author-social .widget-content"],
   ["span[name=\"author-post\"]", ".post-author-widget .widget-content"]].forEach(function (pair) {
    var target = document.querySelector(pair[0]);
    var source = document.querySelector(pair[1]);
    if (!target || !source) return;
    target.insertAdjacentHTML("beforebegin", source.innerHTML);
    source.innerHTML = "";
  });
}

initMainMenu();
initDrawer();
initFeaturedPostWidget();
initPopularPosts();
initPostInjections();
//

//
// Fill alt text from the filename only when an image has none at all
document.addEventListener("DOMContentLoaded", function () {
  document.querySelectorAll("img:not([alt])").forEach(function (img) {
    var src = img.getAttribute("src") || "";
    var name = src.substring(src.lastIndexOf("/") + 1, src.lastIndexOf("."));
    if (name) img.setAttribute("alt", name);
  });
});
// Label links honor the configured posts-per-page
document.querySelectorAll(".Label a, .pixel-max-limit").forEach(function (a) {
  var href = a.getAttribute("href");
  if (href && href.indexOf("max-results=") === -1) a.setAttribute("href", href + "?&max-results=" + perPage);
});
