b:if.script:
//
(function () {
  var body = document.body;
  if (body.classList.contains("item") || body.classList.contains("static_page")) return;
  var older = document.querySelector("a.blog-pager-older-link");
  var pager = document.getElementById("blog-pager");
  if (!older || !pager) return;
  var olderPostsLink = older.getAttribute("href");
  var loading = false;
  var wrap = document.createElement("div");
  wrap.style.cssText = "text-align: center; font-size: 150%;";
  var link = document.createElement("a");
  link.href = "javascript:;";
  link.textContent = "Load more posts";
  var spinner = document.createElement("img");
  spinner.src = "https://lh3.googleusercontent.com/-FiCzyOK4Mew/T4aAj2uVJKI/AAAAAAAAPaY/x23tjGIH7ls/s32/ajax-loader.gif";
  spinner.alt = "";
  spinner.style.display = "none";
  wrap.appendChild(link);
  wrap.appendChild(spinner);
  pager.parentNode.insertBefore(wrap, pager);
  pager.style.display = "none";
  function loadMore() {
    if (loading) return;
    if (!olderPostsLink) { wrap.style.display = "none"; return; }
    loading = true;
    link.style.display = "none";
    spinner.style.display = "inline";
    fetch(olderPostsLink).then(function (r) { return r.text(); }).then(function (html) {
      var doc = new DOMParser().parseFromString(html, "text/html");
      var newLink = doc.querySelector("a.blog-pager-older-link");
      olderPostsLink = newLink ? newLink.getAttribute("href") : "";
      if (!olderPostsLink) wrap.style.display = "none";
      var pickup = document.querySelector(".ajax_pickup");
      var newPickup = doc.querySelector(".ajax_pickup");
      if (pickup && newPickup) {
        Array.prototype.slice.call(newPickup.children).forEach(function (child) {
          pickup.appendChild(document.importNode(child, true));
        });
      }
      document.querySelectorAll(".pixel-max-limit").forEach(function (a) {
        var href = a.getAttribute("href");
        if (href && href.indexOf("max-results=") === -1) a.setAttribute("href", href + "?&max-results=" + perPage);
      });
      simplifyFormatTimes();
      spinner.style.display = "none";
      link.style.display = "inline";
      loading = false;
    }).catch(function () {
      spinner.style.display = "none";
      link.style.display = "inline";
      loading = false;
    });
  }
  link.addEventListener("click", loadMore);
  window.addEventListener("scroll", function () {
    var pos = window.scrollY + window.innerHeight;
    var height = Math.max(document.documentElement.scrollHeight, document.documentElement.clientHeight);
    if (height - pos < 150) loadMore();
  }, { passive: true });
})();
//
